  await evaluate(`foilTest.start(1,{free:true,assist:${assist},conditions:{wind:8.2,swell:0,gust:0}})`);await frames();
  const key=direction>0?'s':'w',code=direction>0?'KeyS':'KeyW',virtual=direction>0?83:87;
  if(tablet||phone){
   const p=await evaluate("(()=>{const r=document.getElementById('joystick').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2,radius:Math.min(r.width,r.height)*.33}})()");
   const touch={x:p.x,y:p.y,id:71};await cdp('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[touch]});touch.y+=direction*p.radius*.35;await cdp('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[touch]});
  }else await cdp('Input.dispatchKeyEvent',{type:'keyDown',key,code,windowsVirtualKeyCode:virtual});
  await frames();const input=await evaluate('foilTest.control.balance');assert.ok(input*direction>.2);
  const result=await evaluate(`(()=>{const s=foilTest.session;Object.assign(s,{standing:true,standAmount:1,height:.4,speed:5.5,foiling:true,pitch:.024,trim:.68,balance:0,vertical:0});s.controls.trim=.68;foilTest.step(.8);foilTest.previewPose({});return {pitch:s.pitch,vertical:s.vertical,height:s.height,crashes:s.stats.crashes,hipOffset:foilTest.polish.rider.hipOffset,pose:foilTest.boardPose(${JSON.stringify(points)})};})()`);
  if(tablet||phone)await cdp('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});else await cdp('Input.dispatchKeyEvent',{type:'keyUp',key,code,windowsVirtualKeyCode:virtual});
  parity(result.pose);assert.equal(result.crashes,0);assert.ok(result.pitch*direction>0&&result.vertical*direction>0&&(result.height-.4)*direction>0,JSON.stringify(result));
