 const heights=[];for(let i=0;i<12;i++){await evaluate(`foilTest.previewPose({mode:'swimming',speed:2.2,swimVelocity:2.2,swimEffort:1,swimPhase:${i*Math.PI/6},jumpTime:0})`);await frames();const rig=await evaluate('foilTest.polish.rider');for(const [a,b] of rig.arms)assert.ok(Math.abs(a-.31)<.005&&Math.abs(b-.29)<.005,JSON.stringify(rig));for(const [a,b] of rig.legs)assert.ok(Math.abs(a-.43)<.005&&Math.abs(b-.43)<.005);assert.ok(Math.abs(rig.swim.roll)<.4);heights.push(...rig.swim.handHeights);if(i%3===0)await screenshot('swim-phase-'+i);}
